import type * as THREE from 'three'

export type TeammateId = 'lyra' | 'rook' | 'pip'
export type EnemyVariant = 'scout' | 'heavy' | 'turret' | 'carrier'
export type LaserOwner = 'player' | 'enemy'

export interface InputState {
  keys: Set<string>
  justPressed: Set<string>
}

export interface WorldState {
  distance: number
  speed: number
  boost: boolean
  /** Shared simulation clock; all gameplay timers use this value. */
  time: number
  /** Set while a hidden tab is paused so the first resumed frame is bounded. */
  resumePending: boolean
}

export interface PlayerState {
  position: THREE.Vector3
  target: THREE.Vector3
  velocity: THREE.Vector3
  invincibleUntil: number
  barrel: {
    active: boolean
    direction: number
    startedAt: number
  }
}

export interface FlightRuntime {
  input: InputState
  world: WorldState
  player: PlayerState
}

export interface LaserHandle {
  id: string
  owner: LaserOwner
  position: THREE.Vector3
  previousPosition: THREE.Vector3
  alive: boolean
}

export interface EnemyHandle {
  id: string
  variant: EnemyVariant
  position: THREE.Vector3
  previousPosition: THREE.Vector3
  radius: number
  alive: boolean
}

export interface EnemySpawn {
  id: string
  variant: EnemyVariant
  x: number
  y: number
  z: number
  bornAt: number
  target?: TeammateId
  health: number
  maxHealth: number
}

